import center from '@turf/center'
import simplify from '@turf/simplify'
import { coordEach } from '@turf/meta'
import { geojsonToStlAsync, buildBuildingInfoText, buildDomainText } from './geojsonToStl.js'

/**
 * Parse JSON text and check for a non-empty FeatureCollection of Features.
 * Properties must be an object, null, or absent. Geometry is left unchanged.
 * Invalid JSON or an invalid collection/feature structure throws an error.
 *
 * Input:
 *   '{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":101},"geometry":null}]}'
 * Output:
 *   {
 *     type: 'FeatureCollection',
 *     features: [{ type: 'Feature', properties: { id: 101 }, geometry: null }]
 *   }
 */
export function parseGeoJson(text) {
  const collection = JSON.parse(text.replace(/^\uFEFF/, ''))
  if (collection?.type !== 'FeatureCollection' || !Array.isArray(collection.features)) {
    throw new Error('GeoJSON must be a FeatureCollection with a features array.')
  }
  if (!collection.features.length) throw new Error('GeoJSON must contain at least one feature.')
  collection.features.forEach((feature, index) => {
    if (
      feature?.type !== 'Feature' ||
      (feature.properties != null && (typeof feature.properties !== 'object' || Array.isArray(feature.properties)))
    ) {
      throw new Error(`GeoJSON feature ${index + 1} must be a Feature with object or null properties.`)
    }
  })
  return collection
}

/**
 * Copy properties and supply an index only when a feature has no property id.
 * Input: a FeatureCollection with properties { h:10 } on feature 0.
 * Output: a new collection with properties { h:10, id:0 }; geometry is unchanged.
 */
export function prepareCityBem(collection) {
  return {
    ...collection,
    features: collection.features.map((feature, index) => ({
      ...feature,
      properties: { id: index, ...feature.properties },
    })),
  }
}

/**
 * Simplify footprints, choose their bounding-box origin and extrude STL solids.
 * Preserve the local-metre or Web-Mercator setting, selected height/year/type fields
 * and default height. h denotes top elevation; min_height denotes the base.
 * Input: prepared building GeoJSON; { heightKey:'h', defaultHeight:10, tolerance:0 }.
 * Output: conversion statistics and five named files: geometry.stl, Building_info.txt,
 * geojson_dataset_for_plotting.geojson, positionSetting.txt and domain.txt.
 * Conversion yields between batches; onProgress receives (done,total).
 */
export async function exportCityBem(collection, options, onProgress = () => {}) {
  const { heightKey, yearKey, typeKey, defaultHeight, tolerance, legacyProjection } = options
  if (!Number.isFinite(tolerance) || tolerance < 0)
    throw new Error('Simplify tolerance must be zero or a positive number.')
  if (defaultHeight !== null && (!Number.isFinite(defaultHeight) || defaultHeight <= 0)) {
    throw new Error('Default height must be positive, or empty to skip missing heights.')
  }
  if (!heightKey) throw new Error('Choose a height attribute.')
  coordEach(collection, (coordinate) => {
    if (
      !Array.isArray(coordinate) ||
      coordinate.length < 2 ||
      !coordinate.slice(0, 2).every(Number.isFinite) ||
      Math.abs(coordinate[0]) > 180 ||
      Math.abs(coordinate[1]) >= 90
    ) {
      throw new Error('Building coordinates must be valid WGS84 longitude/latitude away from the poles.')
    }
  })
  const prepared = tolerance ? simplify(collection, { tolerance, highQuality: true, mutate: false }) : collection
  const origin = center(prepared).geometry.coordinates
  const result = await geojsonToStlAsync(
    prepared,
    {
      origin,
      heightProperty: heightKey,
      defaultHeight: defaultHeight ?? undefined,
      projection: legacyProjection ? 'web-mercator' : 'local',
    },
    { batchSize: 250, onProgress },
  )
  if (!result.stats.triangles) throw new Error('No usable building or terrain geometry was generated.')
  return {
    result,
    files: [
      { name: 'geometry.stl', content: result.chunks.join('') },
      { name: 'Building_info.txt', content: buildBuildingInfoText(result, prepared, yearKey, typeKey, true) },
      { name: 'geojson_dataset_for_plotting.geojson', content: JSON.stringify(prepared) },
      {
        name: 'positionSetting.txt',
        content: JSON.stringify({
          type: 'Feature',
          properties: { projection: result.projection, note: 'STL origin (0,0,0) in WGS84' },
          geometry: { type: 'Point', coordinates: result.origin },
        }),
      },
      { name: 'domain.txt', content: buildDomainText(result) },
    ],
  }
}
