<script setup>
import { computed, ref, shallowRef } from 'vue'
import { parseGeoJson, prepareCityBem, exportCityBem } from './cityBemExporter.js'
import { zipFiles } from '../shared/archive.js'
import { downloadFile } from '../shared/download.js'

const collection = shallowRef(null)
const heightKey = ref(null),
  yearKey = ref(null),
  typeKey = ref(null)
const defaultHeight = ref(10),
  tolerance = ref(0.000001),
  legacyProjection = ref(false)
const loading = ref(false),
  exporting = ref(false),
  progress = ref(0),
  error = ref(''),
  result = ref('')
const busy = computed(() => loading.value || exporting.value)
const properties = computed(() =>
  [...new Set(collection.value?.features.flatMap((feature) => Object.keys(feature.properties ?? {})))].sort(),
)
function clearResult() {
  result.value = ''
  error.value = ''
}
async function loadGeoJson(selected) {
  clearResult()
  collection.value = null
  heightKey.value = null
  yearKey.value = null
  typeKey.value = null
  const file = Array.isArray(selected) ? selected[0] : selected
  if (!file) return
  loading.value = true
  try {
    collection.value = prepareCityBem(parseGeoJson(await file.text()))
    heightKey.value = properties.value.find((key) => /^(h|height|hauteur|bldg_height)$/i.test(key)) ?? null
  } catch (failure) {
    error.value = `Could not read GeoJSON: ${failure.message}`
  } finally {
    loading.value = false
  }
}
async function exportFile() {
  if (!collection.value || !heightKey.value || busy.value) return
  clearResult()
  exporting.value = true
  progress.value = 0
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    const output = await exportCityBem(
      collection.value,
      {
        heightKey: heightKey.value,
        yearKey: yearKey.value,
        typeKey: typeKey.value,
        defaultHeight: defaultHeight.value === '' || defaultHeight.value == null ? null : Number(defaultHeight.value),
        tolerance: Number(tolerance.value),
        legacyProjection: legacyProjection.value,
      },
      (done, total) => {
        progress.value = total ? Math.round((done / total) * 100) : 0
      },
    )
    downloadFile(await zipFiles(output.files), 'CityBEM_input.zip', 'application/zip')
    const { buildings, triangles, skipped } = output.result.stats
    result.value = `${buildings} building solids and ${triangles} facets exported; ${skipped.length} items skipped. Downloaded: CityBEM_input.zip.`
  } catch (failure) {
    error.value = `Could not export CityBEM input: ${failure.message}`
  } finally {
    exporting.value = false
    progress.value = 0
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: Tiêu đề trên VaCard; form nhận GeoJSON, chọn thuộc tính và cấu hình xuất CityBEM, thông báo kết quả đặt dưới form. -->
  <section>
    <h1 class="page-title">CityBEM Export</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportFile" @input="clearResult">
          <VaFileUpload
            id="bem-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="GeoJSON file"
            file-types=".geojson,.json,application/geo+json"
            :disabled="busy"
            @update:modelValue="loadGeoJson"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <p v-if="collection" class="text-sm text-secondary" data-testid="bem-summary">
            {{ collection.features.length }} features
          </p>
          <VaSelect
            id="bem-height"
            v-model="heightKey"
            text-by="title"
            value-by="value"
            label="Height attribute (m)"
            aria-label="Height attribute (m)"
            :options="properties"
            :disabled="busy || !collection"
            @update:modelValue="clearResult"
          />
          <VaSelect
            id="bem-year"
            v-model="yearKey"
            text-by="title"
            value-by="value"
            label="Year of construction attribute"
            aria-label="Year of construction attribute"
            :options="properties"
            clearable
            :disabled="busy || !collection"
            @update:modelValue="clearResult"
          />
          <VaSelect
            id="bem-type"
            v-model="typeKey"
            text-by="title"
            value-by="value"
            label="Building type attribute"
            aria-label="Building type attribute"
            :options="properties"
            clearable
            :disabled="busy || !collection"
            @update:modelValue="clearResult"
          />
          <VaInput
            id="bem-default-height"
            v-model="defaultHeight"
            label="Default height when missing (m)"
            input-aria-label="Default height when missing (m)"
            type="number"
            min="0.000001"
            step="any"
            clearable
            :disabled="busy"
          />
          <VaInput
            id="bem-tolerance"
            v-model="tolerance"
            label="Simplify tolerance (degrees)"
            input-aria-label="Simplify tolerance (degrees)"
            type="number"
            min="0"
            step="any"
            required
            :disabled="busy"
          />
          <VaSwitch
            v-model="legacyProjection"
            label="Legacy Web-Mercator units"
            :disabled="busy"
            @update:modelValue="clearResult"
          />
          <VaProgressBar v-if="exporting" :model-value="progress" height="18" color="primary"
            ><span>{{ progress }} %</span></VaProgressBar
          >
          <VaButton type="submit" color="primary" :disabled="!collection || !heightKey || busy" :loading="exporting"
            >Export</VaButton
          >
        </VaForm>
        <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
